PCBServer.PreProcess;
Try
  Track := PCBServer.PCBObjectFactory(eTrackObject, eNoDimension, eCreate_Default);
  Track.X1 := MilsToCoord(1000); Track.Y1 := MilsToCoord(1000);
  Track.X2 := MilsToCoord(2000); Track.Y2 := MilsToCoord(1000);
  Track.Width := MilsToCoord(10); Track.Layer := eTopLayer;
  Board.AddPCBObject(Track);
Finally
  PCBServer.PostProcess;
End;

PCBServer.SendMessageToRobots(Via.I_ObjectAddress, c_Broadcast, PCBM_BeginModify, c_NoEventData);
Via.Size := MMsToCoord(0.6);
PCBServer.SendMessageToRobots(Via.I_ObjectAddress, c_Broadcast, PCBM_EndModify, c_NoEventData);

Rule := PCBServer.PCBRuleFactory(eRule_MaxMinWidth);
Rule.Name := 'Width_Power';
Rule.Scope1Expression := 'InNetClass(''POWER'')';
Rule.MinWidth := MMsToCoord(0.3); Rule.MaxWidth := MMsToCoord(2); Rule.FavoredWidth := MMsToCoord(0.5);
Board.AddPCBObject(Rule);

Iterator := Board.BoardIterator_Create;
Iterator.AddFilter_ObjectSet(MkSet(eTextObject));
Iterator.AddFilter_LayerSet(MkSet(eMechanical13));
T := Iterator.FirstPCBObject;
While T <> Nil Do Begin
  Next := Iterator.NextPCBObject;
  Board.RemovePCBObject(T);
  PCBServer.DestroyPCBObject(T);
  T := Next;
End;
Board.BoardIterator_Destroy(Iterator);

Rect := Comp.BoundingRectangle;
SI := Board.SpatialIterator_Create;
SI.AddFilter_ObjectSet(MkSet(eViaObject));
SI.AddFilter_LayerSet(AllLayers);
SI.AddFilter_Area(Rect.Left, Rect.Bottom, Rect.Right, Rect.Top);
Via := SI.FirstPCBObject;
While Via <> Nil Do Begin Inc(Count); Via := SI.NextPCBObject; End;
Board.SpatialIterator_Destroy(SI);

Var X, Y : TCoord;
Begin
  If Not Board.ChooseLocation(X, Y, 'Click the new origin') Then Exit;
  Board.XOrigin := X; Board.YOrigin := Y;
  Board.GraphicalView_ZoomRedraw;
End;

L := Board.LayerStack.FirstLayer;
While L <> Nil Do Begin
  Report.Add(L.Name + ' : ' + Layer2String(L.LayerID) + ' Cu ' + CoordToMils(L.CopperThickness) + ' mil');
  L := Board.LayerStack.NextLayer(L);
End;

BO := Board.BoardOutline;
R := BO.BoundingRectangle;
ShowMessage(Format('Board %.2f x %.2f mm', [CoordToMMs(R.Right - R.Left), CoordToMMs(R.Top - R.Bottom)]));

PCBServer.PreProcess;
For i := 0 To Board.SelectecObjectCount - 1 Do Begin
  Prim := Board.SelectecObject[i];
  If Prim.ObjectId = eTrackObject Then Prim.Width := MMsToCoord(0.25);
End;
PCBServer.PostProcess;
Board.ViewManager_FullUpdate;

Board.DisplayUnit := eMetric;
Board.SnapGridSizeX := MMsToCoord(0.1);
Board.SnapGridSizeY := MMsToCoord(0.1);
Board.GraphicalView_ZoomRedraw;

For L := eMechanical1 To eMechanical16 Do
  If Board.LayerIsUsed[L] Then Board.LayerIsDisplayed[L] := True;
Board.ViewManager_FullUpdate;

GI := Comp.GroupIterator_Create;
GI.AddFilter_ObjectSet(MkSet(ePadObject));
Pad := GI.FirstPCBObject;
While Pad <> Nil Do Begin
  If Pad.Net <> Nil Then Report.Add(Comp.Name.Text + '-' + Pad.Name + ' : ' + Pad.Net.Name);
  Pad := GI.NextPCBObject;
End;
Comp.GroupIterator_Destroy(GI);

Lib := PCBServer.GetCurrentPCBLibrary;
LI := Lib.LibraryIterator_Create;
LI.SetState_FilterAll;
FP := LI.FirstPCBObject;
While FP <> Nil Do Begin
  Report.Add(FP.Name + ' height ' + CoordToMMs(FP.Height));
  FP := LI.NextPCBObject;
End;
Lib.LibraryIterator_Destroy(LI);

FP := PCBServer.CreatePCBLibComp;
FP.Name := 'TP_1MM';
Pad := PCBServer.PCBObjectFactory(ePadObject, eNoDimension, eCreate_Default);
Pad.Name := '1'; Pad.Layer := eTopLayer; Pad.TopXSize := MMsToCoord(1); Pad.TopYSize := MMsToCoord(1); Pad.HoleSize := 0;
FP.AddPCBObject(Pad);
Lib.RegisterComponent(FP);
Lib.Board.ViewManager_FullUpdate;

It := Board.BoardIterator_Create;
It.AddFilter_ObjectSet(MkSet(eNetObject));
It.AddFilter_LayerSet(AllLayers);
Net := It.FirstPCBObject;
While Net <> Nil Do Begin
  If Pos('GND', Net.Name) = 1 Then Net.Color := $00FF00;
  Net := It.NextPCBObject;
End;
Board.BoardIterator_Destroy(It);

Poly.PointCount := 4;
S.Kind := ePolySegmentLine;
S.vx := MMsToCoord(0);  S.vy := MMsToCoord(0);  Poly.Segments[0] := S;
S.vx := MMsToCoord(50); S.vy := MMsToCoord(0);  Poly.Segments[1] := S;
S.vx := MMsToCoord(50); S.vy := MMsToCoord(30); Poly.Segments[2] := S;
S.vx := MMsToCoord(0);  S.vy := MMsToCoord(30); Poly.Segments[3] := S;
Poly.PolyHatchStyle := ePolySolid;
Poly.Rebuild;
Board.AddPCBObject(Poly);

Contour := PCBServer.PCBContourFactory;
Contour.AddPoint(MMsToCoord(0), MMsToCoord(0));
Contour.AddPoint(MMsToCoord(5), MMsToCoord(0));
Contour.AddPoint(MMsToCoord(5), MMsToCoord(5));
Contour.AddPoint(MMsToCoord(0), MMsToCoord(5));
Reg := PCBServer.PCBObjectFactory(eRegionObject, eNoDimension, eCreate_Default);
Reg.SetOutlineContour(Contour);
Reg.Layer := eTopLayer;
Board.AddPCBObject(Reg);

It := Board.BoardIterator_Create;
It.AddFilter_ObjectSet(MkSet(eTextObject));
It.AddFilter_LayerSet(MkSet(eTopOverlay, eBottomOverlay));
T := It.FirstPCBObject;
While T <> Nil Do Begin
  If T.IsDesignator Then Begin T.Size := MMsToCoord(1.0); T.Width := MMsToCoord(0.15); End;
  T := It.NextPCBObject;
End;
Board.BoardIterator_Destroy(It);

F := PCBServer.PCBObjectFactory(eFillObject, eNoDimension, eCreate_Default);
F.X1Location := MMsToCoord(10); F.Y1Location := MMsToCoord(10);
F.X2Location := MMsToCoord(20); F.Y2Location := MMsToCoord(15);
F.Layer := eKeepOutLayer; F.IsKeepout := True;
Board.AddPCBObject(F);

It := Board.BoardIterator_Create;
It.AddFilter_ObjectSet(MkSet(eRuleObject));
It.AddFilter_LayerSet(AllLayers);
Rule := It.FirstPCBObject;
While Rule <> Nil Do Begin
  Report.Add(Rule.Name + ' [' + Rule.Scope1Expression + '] enabled=' + BoolToStr(Rule.Enabled));
  Rule := It.NextPCBObject;
End;
Board.BoardIterator_Destroy(It);

Case Prim.ObjectId Of
  eTrackObject : Inc(Tracks);
  eViaObject   : Inc(Vias);
  ePadObject   : Inc(Pads);
End;

Pitch := MMsToCoord(0.5);
For i := 0 To 9 Do Begin
  Via := PCBServer.PCBObjectFactory(eViaObject, eNoDimension, eCreate_Default);
  Via.X := X0 + i * Pitch; Via.Y := Y0;
  Via.Size := MMsToCoord(0.5); Via.HoleSize := MMsToCoord(0.25);
  Via.LowLayer := eTopLayer; Via.HighLayer := eBottomLayer;
  Board.AddPCBObject(Via);
End;

PCBServer.PreProcess;
... add tracks ...
PCBServer.PostProcess;
Board.ConnectivelyValidateNets;
Board.ViewManager_FullUpdate;

PCBServer.PreProcess;
Comp := Board.GetPcbComponentByRefDes('C7');
PCBServer.SendMessageToRobots(Comp.I_ObjectAddress, c_Broadcast, PCBM_BeginModify, c_NoEventData);
Comp.Rotation := 180;
Comp.NameOn := True; Comp.CommentOn := False;
PCBServer.SendMessageToRobots(Comp.I_ObjectAddress, c_Broadcast, PCBM_EndModify, c_NoEventData);
PCBServer.PostProcess;

It := Board.BoardIterator_Create;
It.AddFilter_ObjectSet(MkSet(eViaObject));
It.AddFilter_LayerSet(AllLayers);
Via := It.FirstPCBObject;
While Via <> Nil Do Begin
  If Via.HoleSize < MMsToCoord(0.3) Then Begin
    Via.IsTenting_Top := True; Via.IsTenting_Bottom := True;
  End;
  Via := It.NextPCBObject;
End;
Board.BoardIterator_Destroy(It);

Report := TStringList.Create;
Try
  Report.Add('Designator,Footprint,X_mm,Y_mm,Rot,Layer');
  It := Board.BoardIterator_Create;
  It.AddFilter_ObjectSet(MkSet(eComponentObject));
  It.AddFilter_LayerSet(AllLayers);
  C := It.FirstPCBObject;
  While C <> Nil Do Begin
    Report.Add(Format('%s,%s,%.3f,%.3f,%.1f,%s', [C.Name.Text, C.Pattern, CoordToMMs(C.x), CoordToMMs(C.y), C.Rotation, Layer2String(C.Layer)]));
    C := It.NextPCBObject;
  End;
  Board.BoardIterator_Destroy(It);
  Report.SaveToFile(ExtractFilePath(Board.FileName) + 'placement.csv');
Finally
  Report.Free;
End;

Doc := Client.OpenDocument('PCB', 'D:\work\Main.PcbDoc');
If Doc <> Nil Then Begin
  Client.ShowDocument(Doc);
  Board := PCBServer.GetCurrentPCBBoard;
  ... modify ...
  ResetParameters;
  AddStringParameter('ObjectKind', 'FocusedDocument');
  RunProcess('WorkspaceManager:SaveObject');
End;
